<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class AuthorEarning extends Model {protected $fillable=['author_id','order_id','order_item_id','commission_tier_name','gross_amount','platform_fee_amount','net_amount','currency','status','available_at'];protected $casts=['gross_amount'=>'decimal:2','platform_fee_amount'=>'decimal:2','net_amount'=>'decimal:2','available_at'=>'datetime'];public function author(){return $this->belongsTo(User::class,'author_id');}public function order(){return $this->belongsTo(Order::class);}public function item(){return $this->belongsTo(OrderItem::class,'order_item_id');}}